DO $$
DECLARE
  v_book_id INTEGER;
  v_edit_id INTEGER;
  v_editorial_name TEXT := 'Academia Chilena de la Lengua';
  v_title TEXT := 'Al cateo Â´E la laucha refranes y dichos chilenos';
  v_summary TEXT := NULL;
BEGIN
  INSERT INTO wm_books (title, summary, genre_id)
  VALUES (v_title, v_summary, (SELECT id_genre FROM wm_genres WHERE name = 'Sin Clasificar'))
  RETURNING id_book INTO v_book_id;
  INSERT INTO wm_editions (book_id, isbn, publication_year, pages, editorial_id)
  VALUES (v_book_id, '9789569145032', 2020, 109, (SELECT id_editorial FROM wm_editorials WHERE name = 'Academia Chilena de la Lengua'))
  RETURNING id_edition INTO v_edit_id;
  INSERT INTO wm_formats (name) VALUES ('1ra edicion') ON CONFLICT (name) DO NOTHING;
  INSERT INTO wm_edition_format (id_edition, id_format) VALUES (v_edit_id, (SELECT id_format FROM wm_formats WHERE name = '1ra edicion'));
  INSERT INTO wm_book_author (id_book, id_author)
  VALUES (v_book_id, (SELECT id_author FROM wm_authors WHERE name = 'Academia Chilena de la Lengua'))
  ON CONFLICT DO NOTHING;
  INSERT INTO wm_book_subject (id_book, id_subject)
  VALUES (v_book_id, (SELECT id_subject FROM wm_subjects WHERE name = 'Español Chile Modismos, vicios de dicción, etc.'))
  ON CONFLICT DO NOTHING;
  INSERT INTO wm_copies (barcode, signature_topography, copy_number, edition_id, status_id)
  VALUES ('ACAref', 'ACAref', 1, v_edit_id, 1)
  ON CONFLICT (barcode) DO NOTHING;
END $$;

