  v_edit_id INTEGER;
  v_editorial_name TEXT := 'Sin Editorial';
  v_title TEXT := 'Quique hache detective';
  v_summary TEXT := NULL;
BEGIN
  INSERT INTO wm_books (title, summary, genre_id)
  VALUES (v_title, v_summary, (SELECT id_genre FROM wm_genres WHERE name = 'Policial'))
  RETURNING id_book INTO v_book_id;
  INSERT INTO wm_editions (book_id, isbn, publication_year, pages, editorial_id)
  VALUES (v_book_id, NULL, 2000, 100, (SELECT id_editorial FROM wm_editorials WHERE name = 'Sin Editorial'))
  RETURNING id_edition INTO v_edit_id;
  INSERT INTO wm_formats (name) VALUES ('1ra edicion') ON CONFLICT (name) DO NOTHING;
  INSERT INTO wm_edition_format (id_edition, id_format) VALUES (v_edit_id, (SELECT id_format FROM wm_formats WHERE name = '1ra edicion'));
  INSERT INTO wm_book_author (id_book, id_author)
  VALUES (v_book_id, (SELECT id_author FROM wm_authors WHERE name = 'Gómez Sergio'))
  ON CONFLICT DO NOTHING;
  INSERT INTO wm_copies (barcode, signature_topography, copy_number, edition_id, status_id)
  VALUES ('GOMqui', 'GOMqui', 1, v_edit_id, 1)
  ON CONFLICT (barcode) DO NOTHING;
  INSERT INTO wm_copies (barcode, signature_topography, copy_number, edition_id, status_id)
  VALUES ('GOMquid-c1', 'GOMquid-c1', 2, v_edit_id, 1)
  ON CONFLICT (barcode) DO NOTHING;
END $$;

